/**
 * Shared hover state for chart instances.
 *
 * Each chart calls `useChartHoverState(chartId)`. Hover interactions can either
 * be local to a single chart, or synchronised across every chart on the page
 * (controlled by `syncHover`/`syncTooltip`). The sync preferences persist to
 * localStorage so they survive page reloads.
 */

export const HOVER_SYNC_STORAGE_KEY = 'supabase-chart-hover-sync-enabled'
export const TOOLTIP_SYNC_STORAGE_KEY = 'supabase-chart-tooltip-sync-enabled'

export interface ChartHoverState {
  /** The currently hovered data index, or null when nothing is hovered. */
  hoveredIndex: number | null
  /** The id of the chart that owns the current hover, or null. */
  hoveredChart: string | null
  /** True whenever there is an active hover (a non-null hovered index). */
  isHovered: boolean
  /** True only for the chart instance that owns the current hover. */
  isCurrentChart: boolean
  /** Whether hover interactions are synchronised across charts. */
  syncHover: boolean
  /** Whether tooltips are synchronised across charts. */
  syncTooltip: boolean
  setHover: (index: number | null) => void
  clearHover: () => void
  setSyncHover: (enabled: boolean) => void
  setSyncTooltip: (enabled: boolean) => void
}

interface GlobalHoverState {
  hoveredIndex: number | null
  hoveredChart: string | null
  syncHover: boolean
  syncTooltip: boolean
}

const readSyncSettings = (): { syncHover: boolean; syncTooltip: boolean } => {
  if (typeof window === 'undefined') {
    return { syncHover: false, syncTooltip: false }
  }

  try {
    const rawHover = window.localStorage.getItem(HOVER_SYNC_STORAGE_KEY)
    const rawTooltip = window.localStorage.getItem(TOOLTIP_SYNC_STORAGE_KEY)

    const syncHover = rawHover === null ? false : JSON.parse(rawHover) === true
    const syncTooltip = rawTooltip === null ? false : JSON.parse(rawTooltip) === true

    return { syncHover, syncTooltip }
  } catch (error) {
    // Corrupted / non-JSON-parseable values: fall back to disabled sync.
    console.warn('Failed to read chart hover sync settings from localStorage:', error)
    return { syncHover: false, syncTooltip: false }
  }
}

const persistSyncSetting = (key: string, value: boolean) => {
  if (typeof window === 'undefined') return

  try {
    window.localStorage.setItem(key, JSON.stringify(value))
  } catch (error) {
    console.warn('Failed to save chart hover sync setting to localStorage:', error)
  }
}

const globalState: GlobalHoverState = {
  hoveredIndex: null,
  hoveredChart: null,
  ...readSyncSettings(),
}

const subscribers = new Set<() => void>()

const notify = () => {
  subscribers.forEach((callback) => callback())
}

const setGlobalState = (partial: Partial<GlobalHoverState>) => {
  let hasChanged = false
  for (const key of Object.keys(partial) as Array<keyof GlobalHoverState>) {
    if (globalState[key] !== partial[key]) {
      hasChanged = true
      break
    }
  }

  if (!hasChanged) return

  Object.assign(globalState, partial)
  notify()
}

/**
 * Resets the shared hover state back to its defaults. Primarily intended for
 * tests to guarantee isolation between cases.
 */
export const resetChartHoverState = () => {
  globalState.hoveredIndex = null
  globalState.hoveredChart = null
  const { syncHover, syncTooltip } = readSyncSettings()
  globalState.syncHover = syncHover
  globalState.syncTooltip = syncTooltip
  notify()
}

export function useChartHoverState(chartId?: string): ChartHoverState {
  const [, forceRender] = useReducer((count: number) => count + 1, 0)
  const [localHoveredIndex, setLocalHoveredIndex] = useState<number | null>(null)

  // Subscribe to shared state changes so every instance re-renders in sync.
  useEffect(() => {
    const callback = () => forceRender()
    subscribers.add(callback)
    return () => {
      subscribers.delete(callback)
    }
  }, [])

  // Re-hydrate the sync preferences from localStorage on mount so freshly
  // mounted charts pick up persisted settings (e.g. after a page reload).
  useEffect(() => {
    const { syncHover, syncTooltip } = readSyncSettings()
    setGlobalState({ syncHover, syncTooltip })
  }, [])

  const setHover = useCallback(
    (index: number | null) => {
      if (globalState.syncHover) {
        setGlobalState({ hoveredIndex: index, hoveredChart: index === null ? null : chartId ?? null })
      } else {
        setLocalHoveredIndex(index)
      }
    },
    [chartId]
  )

  const clearHover = useCallback(() => {
    if (globalState.syncHover) {
      setGlobalState({ hoveredIndex: null, hoveredChart: null })
    } else {
      setLocalHoveredIndex(null)
    }
  }, [])

  const setSyncHover = useCallback((enabled: boolean) => {
    // No-op when the requested value already matches the current state.
    if (globalState.syncHover === enabled) return

    persistSyncSetting(HOVER_SYNC_STORAGE_KEY, enabled)

    if (!enabled) {
      // Disabling hover sync also disables tooltip sync.
      persistSyncSetting(TOOLTIP_SYNC_STORAGE_KEY, false)
      setGlobalState({ syncHover: false, syncTooltip: false })
    } else {
      setGlobalState({ syncHover: true })
    }
  }, [])

  const setSyncTooltip = useCallback((enabled: boolean) => {
    // Tooltip sync depends on hover sync, so enabling one enables the other.
    const nextSyncHover = enabled ? true : globalState.syncHover

    persistSyncSetting(TOOLTIP_SYNC_STORAGE_KEY, enabled)
    persistSyncSetting(HOVER_SYNC_STORAGE_KEY, nextSyncHover)

    setGlobalState({ syncTooltip: enabled, syncHover: nextSyncHover })
  }, [])

  const { syncHover, syncTooltip } = globalState

  const effectiveIndex = syncHover ? globalState.hoveredIndex : localHoveredIndex
  const effectiveChart = syncHover
    ? globalState.hoveredChart
    : localHoveredIndex === null
      ? null
      : chartId ?? null

  return {
    hoveredIndex: effectiveIndex,
    hoveredChart: effectiveChart,
    isHovered: effectiveIndex !== null,
    isCurrentChart: effectiveChart !== null && effectiveChart === chartId,
    syncHover,
    syncTooltip,
    setHover,
    clearHover,
    setSyncHover,
    setSyncTooltip,
  }
}
